import json
from collections import defaultdict

with open('/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u097/system/state/workspace/programs/task-3b5f776f.json', 'r') as f:
    data = json.load(f)

pairs = data['pairs']

# First, figure out background for each pair
for i, p in enumerate(pairs):
    vals = set(val for row in p['input'] for val in row)
    most_common = max(vals, key=vals.count)
    print(f"Pair {i}: background = {most_common}, shape = {len(p['input'])}x{len(p['input'][0])}")

# Detect background dynamically
def get_bg(matrix):
    vals = set()
    for row in matrix:
        for v in row:
            vals.add(v)
    return max(vals, key=vals.count)

def transform(matrix):
    H, W = len(matrix), len(matrix[0])
    bg = get_bg(matrix)

    output = [[bg] * W for _ in range(H)]

    # Find special cells
    special = []
    for r in range(H):
        for c in range(W):
            if matrix[r][c] != bg:
                special.append((r, c, matrix[r][c]))

    if len(special) < 2:
        return output

    # Group by diagonal
    by_main = defaultdict(list)   # r-c
    by_anti = defaultdict(list)   # r+c

    for sr, sc, sclr in special:
        by_main[sr - sc].append((sr, sc, sclr))
        by_anti[sr + sc].append((sr, sc, sclr))

    # Main diagonals: first fills up-left, last fills down-right
    for d, cells in by_main.items():
        if len(cells) >= 2:
            cells = sorted(cells, key=lambda x: x[0])
            # First fills up-left (-1,-1)
            sr, sc, sclr = cells[0]
            nr, nc = sr - 1, sc - 1
            while nr >= 0 and nc >= 0:
                if output[nr][nc] == bg:
                    output[nr][nc] = sclr
                else:
                    break
                nr -= 1
                nc -= 1

            # Last fills down-right (1,1)
            sr, sc, sclr = cells[-1]
            nr, nc = sr + 1, sc + 1
            while nr < H and nc < W:
                if output[nr][nc] == bg:
                    output[nr][nc] = sclr
                else:
                    break
                nr += 1
                nc += 1

    # Anti diagonals: first fills up-right, last fills down-left
    for d, cells in by_anti.items():
        if len(cells) >= 2:
            cells = sorted(cells, key=lambda x: x[0])
            # First fills up-right (-1,1)
            sr, sc, sclr = cells[0]
            nr, nc = sr - 1, sc + 1
            while nr >= 0 and nc < W:
                if output[nr][nc] == bg:
                    output[nr][nc] = sclr
                else:
                    break
                nr -= 1
                nc += 1

            # Last fills down-left (1,-1)
            sr, sc, sclr = cells[-1]
            nr, nc = sr + 1, sc - 1
            while nr < H and nc >= 0:
                if output[nr][nc] == bg:
                    output[nr][nc] = sclr
                else:
                    break
                nr += 1
                nc -= 1

    return output

# Test on all pairs
print("\nTesting transform:")
for i, p in enumerate(pairs):
    result = transform(p['input'])
    match = result == p['output']
    print(f"Pair {i}: {'PASS' if match else 'FAIL'}")

